    # NOTE: `tests` is intentionally NOT declared here. It lives on the concrete
    # subclasses (`UserToolSource`, `YamlToolSource`) so that the slim
    # `UserToolSourceAuthoringView` can inherit everything *except* the test
    # field. The test-assertion DSL pulled in by `tests` is ~70% of the JSON
    # schema; keeping it off the authoring view is what shrinks the
    # structured-output schema handed to LLM tool-generation agents.

    @model_validator(mode="before")
    @classmethod
    def normalize_items(cls, values):
        if isinstance(values, dict):
            normalize_dict(values, ["inputs", "outputs"])
        return values

    @field_validator("name", "version", mode="after")
    @classmethod
    def _reject_blank_strings(cls, v: str | None) -> str | None:
        if v is not None and not v.strip():
            raise PydanticCustomError(
                "dynamic_tool.blank_string",
                "must not be empty or whitespace",
            )
        return v

    @model_validator(mode="after")
    def _check_input_refs(self) -> "_DynamicToolSourceBase":
        declared_inputs: set[str] = {param.root.name for param in self.inputs}
        referenced: set[str] = _command_input_refs(self.shell_command)
        for configfile in self.configfiles or []:
            referenced |= _command_input_refs(configfile.content)
        if undeclared := sorted(referenced - declared_inputs):
            joined = "; ".join(
                f"references inputs.{name} but no input named '{name}' is declared" for name in undeclared
            )
            raise PydanticCustomError(
                "dynamic_tool.undeclared_input_ref",
                joined,
            )
        return self

    @model_validator(mode="after")
    def _check_output_claims(self) -> "_DynamicToolSourceBase":
        errors: list[str] = []
        for output in self.outputs:
            if isinstance(output, IncomingToolOutputDataset):
                if not output.from_work_dir and not output.discover_datasets:
                    errors.append(
                        f"output '{output.name}' must set 'from_work_dir' or 'discover_datasets' "
                        "(otherwise its bytes will never be claimed from the working directory)"
                    )
            elif isinstance(output, IncomingToolOutputCollection):
                if not output.discover_datasets:
                    errors.append(
                        f"output collection '{output.name}' must set 'discover_datasets' "
                        "(otherwise no elements will be claimed from the working directory)"
                    )
        if errors:
            raise PydanticCustomError(
                "dynamic_tool.output_unclaimed",
                "; ".join(errors),
            )
        return self


class CondaPackage(BaseModel):
    """A conda package a tool wraps -- a name plus an optional pinned version.

    Inferred by tool-authoring agents (from a tool's command/configfiles) so a
    verified ``quay.io/biocontainers`` image can be resolved deterministically
    rather than guessed. ``UserToolSource`` persists only a single ``container``
    string and has no package-requirement field, so this is never stored on a
    tool -- it is transient input to container resolution.
    """

    name: str
    version: str | None = None

    help: str | None = None
    optional: bool = False


def _common_internal_kwargs(yaml_param: "_YamlParamBase") -> dict:
    kwargs: dict = {"name": yaml_param.name, "optional": yaml_param.optional}
    if yaml_param.label is not None:
        kwargs["label"] = yaml_param.label
    if yaml_param.help is not None:
        kwargs["help"] = yaml_param.help
    return kwargs


class YamlBooleanParameter(_YamlParamBase):
    type: Literal["boolean"]
    value: bool | None = False

    def to_internal(self) -> BooleanParameterModel:
        return BooleanParameterModel(type="boolean", value=self.value, **_common_internal_kwargs(self))


class YamlIntegerParameter(_YamlParamBase):
    type: Literal["integer"]
    value: int | None = None
    min: int | None = None
    max: int | None = None
    validators: list[YamlNumberValidators] = []

    def to_internal(self) -> IntegerParameterModel:
        return IntegerParameterModel(
            type="integer",
            value=self.value,
            min=self.min,
            max=self.max,
            validators=list(self.validators),
            **_common_internal_kwargs(self),
        )


class YamlFloatParameter(_YamlParamBase):
    type: Literal["float"]
    value: float | None = None
    min: float | None = None
    max: float | None = None
    validators: list[YamlNumberValidators] = []

    def to_internal(self) -> FloatParameterModel:
        return FloatParameterModel(
            type="float",
            value=self.value,
            min=self.min,
            max=self.max,
            validators=list(self.validators),
            **_common_internal_kwargs(self),
        )


class YamlTextParameter(_YamlParamBase):
    type: Literal["text"]
    value: str | None = Field(default=None, alias="value")
    area: bool = False
    validators: list[YamlTextValidators] = []

    def to_internal(self) -> TextParameterModel:
        return TextParameterModel(
            type="text",
            default_value=self.value,
            area=self.area,
            validators=list(self.validators),
            **_common_internal_kwargs(self),
        )


class YamlSelectParameter(_YamlParamBase):
    type: Literal["select"]
    options: Annotated[list[YamlLabelValue], Field(min_length=1)]
    multiple: bool = False
    validators: list[YamlSelectValidators] = []

    def to_internal(self) -> SelectParameterModel:
        return SelectParameterModel(
            type="select",
            options=[o.to_internal() for o in self.options],
            multiple=self.multiple,
            validators=list(self.validators),
            **_common_internal_kwargs(self),
        )


class YamlColorParameter(_YamlParamBase):
    type: Literal["color"]
    value: str | None = None

    def to_internal(self) -> ColorParameterModel:
        return ColorParameterModel(type="color", value=self.value, **_common_internal_kwargs(self))


def _split_format(v):
    # Accept the XML-style comma-separated string form (`format: "txt,tabular"`)
    # as well as a list. Internal `DataParameterModel.extensions` is always a list.
    if isinstance(v, str):
        return [ext.strip().lower() for ext in v.split(",") if ext.strip()]
    return v


class YamlDataParameter(_YamlParamBase):
    type: Literal["data"]
    format: list[str] = ["data"]
    multiple: Annotated[
        bool,
        Field(description="Set true to accept several datasets (a list) for this input instead of one."),
    ] = False
    # NOTE: `min`/`max` (the min/max number of selected datasets) are intentionally
    # NOT exposed here. They only have meaning for a `multiple` input and the runtime
    # rejects them on a single one; in practice authors (and LLMs) reach for `min: 1`
    # to mean "required" -- which a data input already is -- and then the tool fails
    # at build time. Omitting the fields means such a tool is rejected up front with a
    # clear `extra_forbidden` error instead. The internal model still supports them
    # for XML tools.

    @field_validator("format", mode="before")
    @classmethod
    def _coerce_format(cls, v):
        return _split_format(v)

    def to_internal(self) -> DataParameterModel:
        return DataParameterModel(
            type="data",
            extensions=list(self.format),
            multiple=self.multiple,
            **_common_internal_kwargs(self),
        )


class YamlDataCollectionParameter(_YamlParamBase):
    type: Literal["data_collection"]
    collection_type: str | None = None
    format: list[str] = ["data"]

    @field_validator("format", mode="before")
    @classmethod
    def _coerce_format(cls, v):
        return _split_format(v)

    def to_internal(self) -> DataCollectionParameterModel:
        return DataCollectionParameterModel(
            type="data_collection",
            collection_type=self.collection_type,
            extensions=list(self.format),
            value=None,
            **_common_internal_kwargs(self),
        )


YamlConditionalTestParameter = Annotated[YamlBooleanParameter | YamlSelectParameter, Field(discriminator="type")]


class YamlConditionalWhen(BaseModel):
    model_config = ConfigDict(extra="forbid", populate_by_name=True)

    discriminator: bool | str
    parameters: list["YamlGalaxyToolParameter"] = []


class YamlConditionalParameter(_YamlParamBase):
    type: Literal["conditional"]
    test_parameter: YamlConditionalTestParameter
    whens: Annotated[list[YamlConditionalWhen], Field(min_length=1)]

    def to_internal(self) -> ConditionalParameterModel:
        internal_test = self.test_parameter.to_internal()
        default_value = cond_test_parameter_default_value(internal_test)
        internal_whens: list[ConditionalWhen] = []
        for when in self.whens:
            internal_params = [p.root.to_internal() for p in when.parameters]
            internal_whens.append(
                ConditionalWhen(
                    discriminator=when.discriminator,
                    parameters=internal_params,
                    is_default_when=when.discriminator == default_value,
                )
            )
        return ConditionalParameterModel(
            type="conditional",
            test_parameter=internal_test,
            whens=internal_whens,
            **_common_internal_kwargs(self),
        )


class YamlRepeatParameter(_YamlParamBase):
    type: Literal["repeat"]
    parameters: list["YamlGalaxyToolParameter"] = []
    min: int | None = None
    max: int | None = None

    def to_internal(self) -> RepeatParameterModel:
        return RepeatParameterModel(
            type="repeat",
            parameters=[p.root.to_internal() for p in self.parameters],
            min=self.min,
            max=self.max,
            **_common_internal_kwargs(self),
        )


class YamlSectionParameter(_YamlParamBase):
    type: Literal["section"]
    parameters: list["YamlGalaxyToolParameter"] = []

    def to_internal(self) -> SectionParameterModel:
        return SectionParameterModel(
            type="section",
            parameters=[p.root.to_internal() for p in self.parameters],
            **_common_internal_kwargs(self),
        )


YamlGalaxyParameterT = (
    YamlBooleanParameter
    | YamlIntegerParameter
    | YamlFloatParameter
    | YamlTextParameter
    | YamlSelectParameter
    | YamlColorParameter
    | YamlDataParameter
    | YamlDataCollectionParameter
    | YamlConditionalParameter
    | YamlRepeatParameter
    | YamlSectionParameter
)


class YamlGalaxyToolParameter(RootModel):
    root: Annotated[YamlGalaxyParameterT, Field(discriminator="type")]

    def to_internal(self) -> GalaxyParameterT:
        return self.root.to_internal()


