import csv
import sys


ALLOWED = {"True", "1", "TRUE"}


def read_hvg(path):
    genes = set()
    with open(path, newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        if reader.fieldnames is None:
            raise ValueError(f"{path} has no header")
        fields = list(reader.fieldnames)
        index_col = "index" if "index" in fields else fields[0]
        hvg_col = "highly_variable" if "highly_variable" in fields else None
        if hvg_col is None:
            raise ValueError(f"{path} has no highly_variable column")
        for row in reader:
            if str(row.get(hvg_col, "")).strip() in ALLOWED:
                gene = str(row.get(index_col, "")).strip()
                if gene:
                    genes.add(gene)
    return genes


